mapper.update:
UPDATE product_inventory
SET stock_available=stock_available-#{quantity},stock_reserved=stock_reserved+#{quantity}
WHERE product_id=#{productId} AND catalog_lifecycle_status='ACTIVE'
  AND stock_available>=#{quantity}

UPDATE product_inventory
SET stock_reserved=stock_reserved-#{quantity},stock_sold=stock_sold+#{quantity}
WHERE product_id=#{productId} AND stock_reserved>=#{quantity}

UPDATE product_inventory
SET stock_available=stock_available-#{quantity},stock_sold=stock_sold+#{quantity}
WHERE product_id=#{productId} AND stock_available>=#{quantity}

UPDATE product_inventory
SET stock_available=stock_available+#{quantity},stock_reserved=stock_reserved-#{quantity}
WHERE product_id=#{productId} AND stock_reserved>=#{quantity}

UPDATE product_inventory
SET stock_available=stock_available+#{quantity},stock_sold=stock_sold-#{quantity}
WHERE product_id=#{productId} AND stock_sold>=#{quantity}

UPDATE product_inventory
SET merchant_id=#{merchantId},product_name=#{productName},thumbnail_url=#{thumbnailUrl},
  unit_price=#{unitPrice},catalog_lifecycle_status=#{lifecycleStatus},
  catalog_business_version=#{businessVersion}
WHERE product_id=#{productId} AND catalog_business_version<#{businessVersion}

UPDATE product_inventory
SET catalog_business_version=#{businessVersion}
WHERE product_id=#{productId} AND catalog_business_version<#{businessVersion}
